                                        boost::bind(&NCPInstanceBase::check_ncp_entry_update_status, this, _1, "removing SLAAC address", NilReturn()));
                                unicast_address_was_removed(kOriginThreadNCP, address);
                        }
                }
        } else {
                cb(kWPANTUNDStatus_Ok);
        }
}

